<section id="aplikasi" class="section wrap" aria-labelledby="app-title"><div class="app-panel"><div class="app-copy"><span class="eyebrow">${t.appEye}</span><h2 id="app-title">${t.appTitle}</h2><p>${t.appP}</p><ul class="app-benefits">${t.benefits.map(a=>`<li>${ico('check')}${a}</li>`).join('')}</ul><div class="app-buttons"><a class="store-btn" href="https://play.google.com/store/apps/details?id=com.kasministudio.mahabbatimobile">${ico('play')}<span><small>${t.google}</small><strong>Google Play</strong></span></a><a class="text-link" href="${appUrl}">${t.web} ${ico('arrow')}</a></div></div><div class="phone-stage" role="img" aria-label="${t.appAlt}"><div class="phone"></div><div class="phone second"></div></div></div></section>
